<script setup>
import {computed,onMounted,ref} from 'vue'
import {Bell,Calendar,Check,Medal,Warning} from '@element-plus/icons-vue'
import api,{unwrap} from '../api'
import {useAuthStore} from '../store'
const auth=useAuthStore(),data=ref({tasks:[],stats:{},workload:[],notes:[],likes:[]}),weather=ref({hourly:[],current:{}}),day=ref(new Date().toISOString().slice(0,10))
const dayTasks=computed(()=>data.value.tasks.filter(t=>t.dueDate===day.value||t.createdAt===day.value))
const weekDays=computed(()=>Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-d.getDay()+1+i);return d.toISOString().slice(0,10)}))
const weatherLabel=c=>c>=51&&c<=67?'有雨':c<=1?'晴':'多云'
async function load(){const [dashboard,forecast]=await Promise.all([api.get('/dashboard'),api.get('/weather/hourly')]);data.value=unwrap(dashboard);weather.value=unwrap(forecast)}
onMounted(load)
</script>
<template><div class="page dashx"><div class="page-title"><div><p class="eyebrow">TODAY OVERVIEW</p><h1>{{auth.user?.name}}，今天一起把重点做扎实</h1><p>任务、提醒、工作量与天气集中在一个视图中</p></div><div class="weather-now"><b>{{weather.current?.temperature_2m}}°</b><span>{{weather.city}} · {{weatherLabel(weather.current?.weather_code)}}</span><small>{{weather.live?'实时预报':'演示预报'}}</small></div></div>
<div class="micro-kpis"><div><Check/><span>今日任务<b>{{dayTasks.length}}</b></span></div><div><Warning/><span>待核销<b>{{data.tasks.filter(t=>t.status==='verify').length}}</b></span></div><div><Medal/><span>任务积分<b>{{data.stats.points||0}}</b></span></div><div><Bell/><span>师傅点赞<b>{{data.stats.likes||0}}</b></span></div></div>
<div class="dashx-grid"><section class="dx-panel mentor-board"><header><div><h2>师傅留言与叮嘱</h2><p>执行前看一眼，关键步骤不遗漏</p></div><Bell/></header><article v-for="note in data.notes" :key="note.id"><i :class="note.tone"></i><div><b>{{note.tone==='safety'?'安全提醒':'今日重点'}}</b><p>{{note.content}}</p><small>{{note.date}}</small></div></article><article v-for="like in data.likes.slice(0,2)" :key="`l${like.id}`" class="like-note"><i></i><div><b>{{like.from}} 点赞了“{{like.taskTitle}}”</b><p>{{like.comment}}</p><small>奖励 +{{like.points}} 积分</small></div></article><el-empty v-if="!data.notes.length&&!data.likes.length" description="暂无留言"/></section>
<section class="dx-panel workload"><header><div><h2>工作量日历</h2><p>圆点越深，当日任务负荷越高</p></div><Calendar/></header><div class="calendar-head"><span v-for="w in ['一','二','三','四','五','六','日']" :key="w">周{{w}}</span></div><div class="heat-grid"><button v-for="item in data.workload" :key="item.date" :class="[`lv${item.level}`,{active:day===item.date}]" @click="day=item.date"><span>{{Number(item.date.slice(8))}}</span><small>{{item.workload}}</small></button></div><div class="heat-legend"><span>轻</span><i v-for="n in 5" :key="n" :class="`lv${n-1}`"></i><span>重</span></div></section>
<section class="dx-panel hourly"><header><div><h2>逐小时天气</h2><p>温度与降雨概率，辅助安排现场工作</p></div></header><div class="hour-strip"><div v-for="item in weather.hourly" :key="item.time"><small>{{item.time.slice(11,16)}}</small><b>{{item.temperature}}°</b><span>{{weatherLabel(item.code)}}</span><em>降雨 {{item.rain}}%</em></div></div></section>
<section class="dx-panel agenda"><header><div><h2>本周日程</h2><p>选择日期查看当天任务</p></div></header><div class="week-switch"><button v-for="d in weekDays" :key="d" :class="{active:d===day}" @click="day=d"><span>{{['日','一','二','三','四','五','六'][new Date(d).getDay()]}}</span><b>{{d.slice(8)}}</b></button></div><div class="agenda-list"><article v-for="task in dayTasks" :key="task.id"><time>{{task.startTime||'待定'}}</time><div><b>{{task.title}}</b><span>{{task.projectName}} · {{task.assignee}}</span></div><el-tag :type="task.priority==='P0'?'danger':task.priority==='P1'?'warning':'primary'">{{task.priority}}</el-tag></article><el-empty v-if="!dayTasks.length" description="当日无任务" :image-size="55"/></div></section></div></div></template>
<style scoped>
.weather-now{display:flex;align-items:baseline;gap:10px}.weather-now b{font-size:34px;color:#003b7a}.weather-now span{font-weight:700}.weather-now small{color:#8492a6}.micro-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:14px}.micro-kpis>div{background:#fff;border:1px solid #e6eaf0;padding:13px 16px;display:flex;align-items:center;gap:10px;border-radius:6px}.micro-kpis svg{width:18px;color:#087c66}.micro-kpis span{display:flex;align-items:baseline;justify-content:space-between;width:100%;font-size:13px;color:#617086}.micro-kpis b{font-size:22px;color:#182334}.dashx-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.dx-panel{background:#fff;border:1px solid #e5eaf0;border-radius:7px;padding:18px;min-width:0}.dx-panel header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:14px}.dx-panel h2{font-size:16px;margin:0 0 4px}.dx-panel header p{margin:0;color:#8792a2;font-size:12px}.dx-panel header>svg{width:20px;color:#087c66}.mentor-board article{display:flex;gap:12px;padding:12px 0;border-top:1px solid #eef1f5}.mentor-board i{width:4px;background:#e0a128;border-radius:3px}.mentor-board i.safety{background:#d94b42}.mentor-board .like-note i{background:#087c66}.mentor-board p{margin:4px 0;line-height:1.6;color:#425169}.mentor-board small{color:#929cac}.calendar-head,.heat-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:6px}.calendar-head span{text-align:center;font-size:11px;color:#8b96a7}.heat-grid button{border:0;background:transparent;height:42px;position:relative;border-radius:5px;cursor:pointer}.heat-grid button span{display:grid;place-items:center;width:29px;height:29px;margin:auto;border-radius:50%;background:#eef2f4;color:#536175}.heat-grid button small{position:absolute;right:2px;bottom:0;color:#8a95a6;font-size:9px}.heat-grid .lv1 span{background:#d9eee7}.heat-grid .lv2 span{background:#a8d8c9}.heat-grid .lv3 span{background:#5db69d;color:#fff}.heat-grid .lv4 span{background:#087c66;color:#fff}.heat-grid button.active{outline:2px solid #e5a323}.heat-legend{display:flex;justify-content:flex-end;align-items:center;gap:4px;margin-top:10px;font-size:10px;color:#8a95a6}.heat-legend i{width:10px;height:10px;background:#eef2f4}.heat-legend .lv1{background:#d9eee7}.heat-legend .lv2{background:#a8d8c9}.heat-legend .lv3{background:#5db69d}.heat-legend .lv4{background:#087c66}.hourly{grid-column:1/-1}.hour-strip{display:grid;grid-template-columns:repeat(12,minmax(68px,1fr));overflow:auto}.hour-strip>div{text-align:center;padding:9px 5px;border-left:1px solid #edf0f3;display:flex;flex-direction:column;gap:5px}.hour-strip small,.hour-strip em{font-style:normal;font-size:10px;color:#8390a2}.hour-strip b{font-size:17px}.hour-strip span{font-size:11px;color:#3c5a75}.agenda{grid-column:1/-1}.week-switch{display:grid;grid-template-columns:repeat(7,1fr);gap:7px}.week-switch button{border:1px solid #e2e7ed;background:#fafbfc;border-radius:5px;padding:8px;cursor:pointer}.week-switch button.active{background:#087c66;color:#fff;border-color:#087c66}.week-switch span{display:block;font-size:10px}.agenda-list article{display:grid;grid-template-columns:55px 1fr auto;align-items:center;gap:12px;padding:11px;border-bottom:1px solid #edf0f3}.agenda-list time{font-weight:700;color:#087c66}.agenda-list span{display:block;font-size:11px;color:#8490a1;margin-top:3px}@media(max-width:900px){.micro-kpis{grid-template-columns:1fr 1fr}.dashx-grid{grid-template-columns:1fr}.hour-strip{grid-template-columns:repeat(12,76px)}.weather-now{display:none}}@media(max-width:520px){.micro-kpis{grid-template-columns:1fr}.dx-panel{padding:13px}}
</style>

